mapper.select:
select

from t_message
where id in (
    select chosen from (
        select coalesce(
            min(case
                when target_device_id = #{deviceId,jdbcType=VARCHAR}
                 and to_user = #{viewer,jdbcType=VARCHAR}
                then id end),
            min(case
                when to_user = #{peer,jdbcType=VARCHAR}
                then id end),
            min(id)
        ) as chosen
        from t_message
        where conversation_tag in

            #{tag,jdbcType=VARCHAR}

          and to_user in (#{viewer,jdbcType=VARCHAR}, #{peer,jdbcType=VARCHAR})
        group by client_msg_id
    ) picked
)

    and id < #{beforeId,jdbcType=BIGINT}

order by id desc
limit #{limit,jdbcType=INTEGER}

select

from t_message
where id in (
    select min(t.id) from t_message t
    where t.conversation_tag in

        #{tag,jdbcType=VARCHAR}

      and t.to_user in (#{viewer,jdbcType=VARCHAR}, #{peer,jdbcType=VARCHAR})
    group by t.client_msg_id
)

    and id < #{beforeId,jdbcType=BIGINT}

order by id desc
limit #{limit,jdbcType=INTEGER}

select

from t_message
where client_msg_id = #{clientMsgId,jdbcType=VARCHAR}
  and target_device_id = #{targetDeviceId,jdbcType=VARCHAR}
limit 1

select

from t_message
where target_device_id = #{deviceId,jdbcType=VARCHAR}
  and delivered = 0
  and to_user = #{toUsername,jdbcType=VARCHAR}
  and id > ifnull((
      select cleared_before_id from t_conversation_clear
      where username = #{toUsername,jdbcType=VARCHAR}
        and peer = concat('tag:', conversation_tag)
  ), 0)
order by id asc
limit #{limit,jdbcType=INTEGER}

mapper.update:
update t_message
set read_flag = 1
where to_user = #{toUsername,jdbcType=VARCHAR}
  and conversation_tag in

      #{tag,jdbcType=VARCHAR}

  and read_flag = 0
  and recalled = 0

  and client_msg_id in (
    select client_msg_id from (
      select distinct client_msg_id
      from t_message
      where to_user = #{toUsername,jdbcType=VARCHAR}
        and conversation_tag in

            #{tag,jdbcType=VARCHAR}

        and id <= #{beforeId,jdbcType=BIGINT}
    ) read_ids
  )

