from t_message
where to_user = #{toUsername,jdbcType=VARCHAR}
  and read_flag = 0
  and recalled = 0
  and conversation_tag in

      #{tag,jdbcType=VARCHAR}


  and id > #{afterId,jdbcType=BIGINT}

select max(id) from t_message where conversation_tag in
#{tag,jdbcType=VARCHAR}
and to_user in (#{viewer,jdbcType=VARCHAR}, #{peer,jdbcType=VARCHAR})

